data class UiState(val todos: List<Todo> = emptyList())
sealed interface Intent { data class Add(val text: String) : Intent }
class TodosViewModel : ViewModel() {
    private val _state = MutableStateFlow(UiState())
    val state: StateFlow<UiState> = _state.asStateFlow()
    fun onIntent(intent: Intent) = _state.update { reduce(it, intent) }
    private fun reduce(s: UiState, i: Intent) = when (i) {
        is Intent.Add -> s.copy(todos = s.todos + Todo(i.text))
    }
}
